import type { ReactNode } from "react"
import { FieldGroup } from "@/components/ui/field"
import { cn } from "@/lib/utils"

type Props = {
  title?: ReactNode
  help?: ReactNode
  children?: ReactNode
  headerVisible?: boolean
  className?: string
  hideDivider?: boolean
}

/** A settings section owns both its heading and its field rows. */
export function SettingsSection({
  title,
  help,
  children,
  headerVisible = true,
  className,
  hideDivider = false,
}: Props) {
  return (
    <div
      data-slot="settings-section"
      className={cn(
        "-mx-3 flex min-w-0 flex-col gap-4 px-3",
        headerVisible && "mt-1 pt-3",
        headerVisible && !hideDivider && "border-t border-border",
        className,
      )}
    >
      {headerVisible && (title || help) ? (
        <div data-slot="settings-section-heading">
          {title ? (
            <div
              data-slot="settings-section-title"
              className="text-xs leading-4 font-semibold text-foreground"
            >
              {title}
            </div>
          ) : null}
          {help ? (
            <div className="mt-1 text-xs leading-normal font-normal text-muted-foreground">
              {help}
            </div>
          ) : null}
        </div>
      ) : null}
      {children != null ? (
        <FieldGroup data-settings-section-body="" className="gap-4">
          {children}
        </FieldGroup>
      ) : null}
    </div>
  )
}
